curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" -d "types=public_channel" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data['ok']:
    for ch in data['channels']:
        if 'incident' in ch['name'].lower():
            print(ch['id'], '|', ch['name'], '|', ch.get('topic',{}).get('value','') if isinstance(ch.get('topic'), dict) else ch.get('topic',''), '|', ch.get('is_archived'))
else:
    print('ERROR:', data)
"

curl -s -X POST "https://slack.com/api/users.list" -H "Authorization: Bearer <TOKEN>" | python3 -c "
import json, sys
data = json.load(sys.stdin)
if data['ok']:
    for u in data['members']:
        if 'aisha' in u.get('real_name','').lower():
            print(u['id'], '|', u['real_name'], '|', u.get('deleted', False))
else:
    print('ERROR:', data)
"
